using System;
using System.Collections.Generic;
namespace SnapGrab
{
    internal sealed class HelpTopic
    {
        internal readonly string Title, Body;
        internal HelpTopic(string title, string body) { Title = title; Body = body; }
    }

    internal static partial class UserGuide
    {
        internal static HelpTopic[] Topics { get { return UiText.Language=="en" ? EnglishTopics : ChineseTopics; } }
        private static readonly HelpTopic[] ChineseTopics = {
            new HelpTopic("图片编辑与替换文字", "配置独立图片编辑服务：完整 images/edits 地址、图片模型和密钥。文本/看图连接不等于图片编辑可用。\r\n\r\n打开图片或截图，AI 框选；保护画笔涂抹重要内容，恢复修改擦除保护。普通 AI 发送不使用保护蒙版。\r\n\r\n去字修补清除原字并修补背景；替换文字先修补再由本机按当前字体大小和颜色绘制新字；局部重绘使用输入框的要求。\r\n\r\n请求前确认上传图：包括选区周围最多 32 像素，绿色仅用于预览允许区域。生成可能计费，不自动重试；失败、取消或放弃不应用，等待时修改图片或蒙版会丢弃旧结果。\r\n\r\n生成后预览，再确认并自行保存；保护区及选区外原像素保持不变，可一步撤销恢复原标注。确认生成后旧标注合成为底图，后续新标注仍可编辑。新文字不自动匹配原字形，可能截断；复杂背景可能有边缘接缝。\r\n\r\n已验证本地模拟请求和蒙版合成；真实图片服务质量及 Windows 人工流程尚未实测。"),
            new HelpTopic("AI 局部框选", "在编辑器点击「AI 框选」，在图片上拖出目标区域；青色框仅作提示，不进入保存图片。重新拖动可调整区域，Esc 或「清除AI选区」回到整图。\r\n\r\n输入要求并发送：本次只发送框内当前编辑结果的 PNG 和本次要求，不发送整图及旧会话。图像长边仍受 AI 上传尺寸设置限制，小选区不放大。\r\n\r\n返回后查看确认窗口的橙色编号与对应操作/识别文字，勾选后应用；局部模式始终确认。位置或文字有误时放弃、重新框选再发送；OCR/译文可在结果窗口核对和编辑。不能保证模型每次识别正确。\r\n\r\n局部支持标注、文字、遮挡、模糊、马赛克和 OCR，越界坐标整批拒绝。绘制限制在本次选区内，撤销重做保持边界；框内标注被拖到范围外会被截断。局部裁剪被拒绝，请清除选区后另行裁剪。\r\n\r\n本入口仅执行指令；生成式修改使用「去字修补」「替换文字」「局部重绘」和独立图片编辑服务，见对应帮助。"),
            new HelpTopic("开始使用", "截改 AI · SnipRefine\r\n截图、手工标注、看图对话与 AI 辅助修改。\r\n\r\n三步完成：\r\n1. 选择截图方式：Ctrl+Alt+S 快速截图；Ctrl+Alt+A 可调整框选；PrintScreen 全屏截图。\r\n2. 手工编辑，或打开编辑器 AI 面板描述要求。检查结果，必要时撤销。\r\n3. 选择「保存」「另存为」「复制并保存」或「仅复制」。独立保存保持编辑器打开；放弃不会删除已经保存的文件。\r\n\r\n首次使用 AI：设置 → AI 助手 → 快速配置向导 → 选择服务 → 填写密钥与模型 → 测试连接 / 看图 → 保存配置；接口地址和协议可在高级选项修改。截图和手工标注不需要 AI 密钥。\r\n\r\n左上角圆形问号或 F1 打开本说明。搜索会匹配分类标题和正文，说明可离线阅读。"),
            new HelpTopic("截图与输出", "截图有三种方式，可在「快捷键」页点击按钮，或从托盘菜单启动：\r\n\r\n快速截图（Ctrl+Alt+S）：拖动框选，松开立即保存，按复制设置放入剪贴板，不打开编辑器。\r\n框选截图（Ctrl+Alt+A）：先拖动框选，再拖动框内移动、拖动四边或角点改变大小；点击「确认截图」、Enter 或双击框内确认，进入编辑器。框外拖动可重新框选。\r\n全屏截图（PrintScreen）：截取全部显示器组成的桌面，默认进入编辑器。可在快捷键页关闭「全屏截图后进入编辑器」，改为直接保存并按设置复制。升级后默认行为也采用此设置。\r\n\r\nEsc 或右键放弃框选。三组全局快捷键可分别录制并保存；普通主键需带 Ctrl/Shift/Alt，PrintScreen 可单独使用。三组不能重复。若被系统或其他软件占用，注册会提示失败，并尽量恢复原快捷键；仍可使用按钮截图。\r\n\r\n开启编辑器时，选区进入编辑窗口；关闭编辑器时，按截图输出配置处理。\r\n\r\n「保存」：只保存到配置目录，不复制，编辑器保持打开。Ctrl+S 执行此操作。\r\n「另存为」：选择文件名和 PNG/JPEG 格式；失败时保持编辑内容，可重试。Ctrl+Shift+S 执行此操作。\r\n「复制并保存」：尝试复制当前结果，同时后台写入截图目录，然后关闭编辑器。\r\n保存后可用「打开已保存图片」「打开保存位置」。后台保存或复制失败时，可从最近截图页恢复最近一张失败图片；退出或清空记录会释放该图片。\r\n「仅复制」：复制结果，不新建截图文件。Ctrl+C 执行此操作（正在编辑文字时优先复制文字）。\r\n「放弃」：关闭编辑器，不再输出；此前明确保存的文件仍保留。\r\n\r\n保存路径、日期子目录、文件名、PNG/JPEG 和 JPEG 质量在截图设置中配置。保存结果以实际提示为准；复制失败可能是剪贴板被其他程序占用，保存失败应检查目录权限和磁盘空间。"),
            new HelpTopic("手工编辑", "工具栏支持选择、画笔、直线、箭头、矩形、椭圆、文字、马赛克、裁剪、实心遮挡、视觉模糊和连续序号。小窗口下工具栏会换行。\r\n\r\n先选工具，再设置颜色和线宽；拖动绘制。文字输入后 Enter 提交、Esc 取消输入。选择工具可移动标注、通过右下角调整大小，双击文字修改内容，Delete 删除选中标注。\r\n\r\nCtrl+Z 撤销，Ctrl+Y 重做。方向键移动选中标注，Shift 加快移动。\r\n\r\n可用适应窗口、1:1、缩放按钮和 Ctrl+滚轮查看截图；空格配合拖动平移。编辑选框保持透明，不写入输出图片。\r\n\r\n隐私信息建议使用实心遮挡并检查最终图片；视觉模糊不是可靠的隐私删除方式。"),
            new HelpTopic("AI 修改截图", "在截图编辑器中打开 AI，描述具体区域和目标，例如「用不透明实心遮挡隐藏左上角手机号」「用箭头标出错误提示」「裁剪掉底部空白」。未设置 AI 选区时发送整张当前编辑结果，历史要求仅作参考；AI 局部框选的发送范围见对应帮助。\r\n\r\n支持标注、文字、打码、实心遮挡、模糊、裁剪及 OCR。普通 AI 发送通过模型返回指令编辑；图片重绘使用独立图片服务及专门任务按钮，见图片编辑帮助。\r\n\r\n新配置默认启用应用前确认；在 AI 请求设置可调整。收到修改指令后逐项勾选并确认，放弃则不应用。整图模式仅 OCR 不弹出编辑确认；局部模式有操作时始终确认。之后可以查看修改前/后、结束对比或撤销本次。AI 一次修改合并为一步撤销。\r\n\r\n等待时显示已用秒数，不显示虚构进度。取消请求或按 Esc 停止等待，迟到回复不会应用。失败后要求会恢复到空输入框，方便重试。等待期间手工修改了图片，则旧回复不会覆盖新编辑。\r\n\r\nAI 不会自动保存或复制；确认结果后由你选择输出。显示修改前时请先切回修改后再输出。"),
            new HelpTopic("AI 对话与附件", "双方均使用圆角气泡：AI 回复在左，你的消息在右，不显示角色标签。先选图片并输入修改要求，再点击「图片修改」可带入编辑器；确认要求后发送，最后自行复制或保存。\r\n\r\n主界面右上角侧栏按钮展开或收起 AI 对话。小窗口以覆盖方式展开，大窗口共享内容区域，切换不改变窗口尺寸。\r\n\r\n可选择最近截图或本地 PNG/JPEG/BMP/GIF，缩略图会显示当前附件；移除取消附件。自动附带最新截图默认关闭，需主动启用或手动选图。手动选图优先。旧的未保存截图可能只剩低分辨率预览，界面会说明。\r\n\r\n双击缩略图打开图片：滚轮缩放、按住鼠标拖动平移，适应窗口 / 原尺寸，显示比例，支持复制图片。Esc 关闭预览。\r\n\r\n输入后 Enter 发送，Shift+Enter 换行。等待时发送按钮变为取消，Esc 可取消请求；空闲时 Esc 收起对话。失败可保留要求重试。\r\n\r\n右上方「清空会话」会取消请求并清空会话、输入、附件和最近截图内存缓存，不删除已保存文件。\r\n\r\n主界面对话用于问答，不自动改写附件；要实施图片修改，请进入截图编辑器。"),
            new HelpTopic("提供商与模型", "设置 → AI 助手：新增提供商，选择预设或自定义。内置 OpenAI、DeepSeek、MiMo、MiniMax、Claude、Gemini、通义千问、GLM、Kimi、硅基流动、Ollama 等预设。可用模型以服务控制台权限和接口实际返回为准。\r\n\r\n填写 API 地址、API Key、模型列表与默认模型。OpenAI 兼容接口与 Anthropic 接口协议必须匹配。服务根地址通常会补齐请求路径，完整自定义路径保持原样。不同服务或套餐的密钥不可混用。\r\n\r\n「获取模型」读取接口模型列表；服务不支持时可以手填模型 ID。「测试连接」只验证文本请求；「测试看图」验证图像输入，两种结果都显示在按钮下方。\r\n\r\n文本模型适合对话；截图理解、OCR、AI 标注需要视觉模型。通过看图测试也不表示支持生成式图片编辑。\r\n\r\n点击保存后，成功会收起设置面板；失败会保留窗口并显示原因。模型卡片右侧「编辑」可重新打开设置，「使用中」表示当前提供商。预设跨接口填充会清空旧密钥，保存前请检查。"),
            new HelpTopic("AI 请求设置", "请求超时、输出 tokens、温度、系统代理和修改确认选项在「AI 请求」中设置。保存后作用于后续请求。\r\n\r\n超时太短可能中断慢模型；回复为空或被截断可以增加输出上限，思考模型也会消耗预算。图片长边限制控制上传图像大小：较小更省流量，较大有利于识别细字。\r\n\r\n代理是否可用取决于 Windows 系统代理和服务网络。API Key 使用 Windows DPAPI 在本机加密保存，不应提交到 GitHub。服务可能按调用计费，取消请求不保证服务端停止计费。"),
            new HelpTopic("OCR 与翻译", "截图编辑器中的 OCR 识别截图文字，复制 OCR 将识别文本放入剪贴板。翻译通过视觉模型识别并返回译文，默认不改动图片。\r\n\r\n工具栏「查看识别/译文」打开可编辑结果窗口，支持复制核对后的文字。翻译结果包含模型返回的原文与译文；文本编辑不会修改图片。\r\n\r\n需要已配置且支持图片输入的模型。小字、模糊或复杂排版可能识别错误，重要文字请与原图核对。若要把译文标注到图上，请明确向 AI 描述位置和文字。"),
            new HelpTopic("最近截图", "最近截图页保留本次运行最多 6 张缩略图，点击刷新更新，清空记录会释放最近截图及最新原图缓存，不删除已保存文件。\r\n\r\n已保存项可打开原文件；未保存的历史项只保留缩略图，最新截图另保留原图供对话使用。默认重启后记录不恢复。开启「跨重启保留已保存图片路径」后，最近列表最多保留 20 项，并在下次启动加载其中已保存的图片；索引位于配置目录的 saved-history.txt，仅记录本机文件路径和时间，不额外保存图片。关闭此选项或清空记录会删除索引，不删除原图片。历史设置默认关闭。\r\n\r\n图片文件已被移动、删除或保存失败时无法打开原文件，可重新从本地选择。"),
            new HelpTopic("主题与窗口", "外观中可切换明亮或深色主题，立即预览，保存设置后下次启动沿用。按钮采用扁平玻璃质感和统一圆角。\r\n\r\n拖动标题栏移动窗口；拖动边缘或角落调整大小；标题栏 □ 或双击标题栏最大化 / 恢复。F11 进入或退出全屏，全屏时 Esc 返回。\r\n\r\nAI 侧栏默认收起，右上角按钮切换，动画可依设置关闭。窗口最小尺寸用于保留基础操作空间，较窄设置页可滚动。"),
            new HelpTopic("后台与配置", "手动双击程序默认打开主窗口；重复启动尝试唤醒现有实例。开机启动使用 --background 参数，并遵循启动时显示主窗口设置。\r\n\r\n启动与后台设置可控制开机启动、启动时显示主窗口、托盘行为、工作集整理和进程优先级。关闭主窗口是否驻留托盘取决于相关设置；要彻底退出可用托盘的退出菜单。\r\n\r\n配置保存在 %APPDATA%/SnapGrab/SnapGrab.ini。程序名为 SnipRefine.exe。替换程序前请先退出，保留配置即可沿用设置。\r\n\r\n源码包包含 src、构建脚本、图标、回归检查和资源压力检查。"),
            new HelpTopic("快捷键", "Ctrl+Alt+A：可调整框选截图（可自定义）\r\nCtrl+Alt+S：快速框选后直接保存（可自定义）\r\nPrintScreen：一键全屏截图（可自定义）\r\nF1：主窗口打开使用说明\r\nF11：主窗口全屏 / 返回\r\nEsc：取消框选；取消编辑文字；取消 AI 请求；关闭预览；全屏返回（根据当前焦点）\r\nCtrl+S：编辑器只保存，保持窗口打开\r\nCtrl+Shift+S：另存为\r\nCtrl+C：编辑器仅复制（文字编辑时复制文字）\r\nCtrl+Z / Ctrl+Y：撤销 / 重做\r\nDelete：删除选中标注\r\nCtrl+0：编辑器适应窗口\r\nCtrl+1：编辑器原尺寸\r\nCtrl+滚轮：编辑器缩放\r\n空格+拖动：编辑器平移\r\nEnter / Shift+Enter：AI 发送 / 换行\r\n\r\nAI 面板全局快捷键仅在设置启用并成功注册时可用。"),
            new HelpTopic("故障与隐私", "密钥保存失败：查看保存提示，检查配置目录权限。连接失败：检查协议、完整地址、模型 ID、账号权限、余额、代理和网络。HTTP 401/403 通常涉及密钥或权限，404 涉及接口或模型，429 涉及限流或额度。\r\n\r\n「返回没有 choices」：服务可能返回错误对象，或其接口并非兼容聊天接口；确认协议和地址，查看完整错误提示。文本测试成功但看图失败时，请换支持图片输入的模型。\r\n\r\n截图和手工编辑在本地进行；发送 AI 时，所附图片与要求会传到配置的服务。敏感内容请先遮挡。AI 结果不保证正确，输出前核对。\r\n\r\n若界面在不同 DPI 或多屏下异常，请记录缩放比例、分辨率、操作步骤和版本号。此版本为 " + Program.VersionText + "。"),
            new HelpTopic("启动排查", "先完整解压再运行程序。完整源码包可双击根目录 Start.cmd，以 Windows .NET Framework 编译器重新生成程序并启动。此入口不需要管理员权限，不会删除用户配置或结束正在运行的进程；若目标程序被占用，请先从托盘退出再重试。\r\n\r\n程序旁保留 SnipRefine.exe.config，用于明确 .NET Framework 4.x 运行环境。启动异常会显示错误类型，并在配置目录生成 startup-error.log；日志仅含版本、CLR、异常类型和方法名，不包含图片、密钥、异常正文或源码路径。\r\n\r\n若启动脚本提示编译失败，保留窗口中的完整错误信息。旧版已经驻留后台时，请先从托盘退出旧版。\r\n\r\nStart.cmd 的命令窗口会保持到程序退出；异常退出时显示退出码并暂停。PowerShell 源码启动失败时显示提示，可改用 Start.cmd 查看编译信息。开启跨重启历史时，旧图片在后台加载，主窗口先显示；清空记录后不会再接受旧加载结果。")
        };
        internal static List<HelpTopic> Search(string query)
        {
            var found = new List<HelpTopic>();
            query = (query ?? "").Trim();
            foreach (HelpTopic topic in Topics)
                if (query.Length == 0 || topic.Title.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0 ||
                    topic.Body.IndexOf(query, StringComparison.OrdinalIgnoreCase) >= 0) found.Add(topic);
            return found;
        }
    }

}
